import math
last=0.0
def control(obs):
    global last
    cam=obs['views'].get('camera')
    hitch=obs['hitch_deg']
    if cam:
        a=math.radians(obs['rig']['trailer_heading_deg'])
        sides=[[],[]]
        for b,d in cam.get('walls',[]):
            b=math.radians(b)
            x=d*math.cos(b); y=d*math.sin(b)
            s=-x*math.cos(a)-y*math.sin(a)
            q=-x*math.sin(a)+y*math.cos(a)
            if s>0.5:
                sides[0 if q<0 else 1].append((s,q))
        vals=[]
        for side in sides:
            side.sort()
            val=None
            for p,q in zip(side,side[1:]):
                if p[0]<=3.5<=q[0]:
                    val=p[1]+(q[1]-p[1])*(3.5-p[0])/max(0.001,q[0]-p[0]); break
            if val is None and side:
                val=min(side,key=lambda p:abs(p[0]-3.5))[1]
            vals.append(val)
        if all(v is not None for v in vals):
            last=(vals[0]+vals[1])/2
    desired=math.degrees(math.atan(5.2*last/12.25))
    desired=max(-32,min(32,desired))
    steer=max(-34,min(34,2.0*hitch-1.3*desired))
    return (steer,-0.65,-23)

