  travel+=max(0,v)*obs['dt']
  if travel>=2.0:
   phase=1
  else:
   return 0,0.4,-41
 if phase==1:
  if h<=7:
   phase=2
   wake('Corner freed and tractor straightened; reassess rails')
   return 0,0,-41
  return 42,-0.3,-41
 return 0,0,-41

